local function a(t)
    local function list(s)
        local out = {}
        for w in (s or ""):gmatch("[^,]+") do out[#out + 1] = w end
        return out
    end
    return {
        aims = list(t.aims), summary = t.summary,
        key_jokers = list(t.jokers), support_jokers = list(t.support),
        consumables = list(t.cons), vouchers = list(t.vouch), deck_edits = t.edits,
        decks = list(t.decks), stage = t.stage, risks = t.risks, src = "guess",
    }
end

